import type { ImageSourcePropType } from "react-native";

/**
 * Signature tab icons as template PNGs (the tab bar tints them).
 * Generated by `bun run icons:build` from components/icons/signatureIcons.ts.
 */
const TAB_ICONS = {
  home: {
    outline: require("@/assets/icons/tabs/home-outline.png"),
    filled: require("@/assets/icons/tabs/home-filled.png"),
  },
  recipes: {
    outline: require("@/assets/icons/tabs/recipes-outline.png"),
    filled: require("@/assets/icons/tabs/recipes-filled.png"),
  },
  plan: {
    outline: require("@/assets/icons/tabs/plan-outline.png"),
    filled: require("@/assets/icons/tabs/plan-filled.png"),
  },
  shop: {
    outline: require("@/assets/icons/tabs/shop-outline.png"),
    filled: require("@/assets/icons/tabs/shop-filled.png"),
  },
} satisfies Record<
  string,
  { outline: ImageSourcePropType; filled: ImageSourcePropType }
>;

/** Outline when idle, filled when selected — like SF Symbols' .fill pairs. */
export const signatureTabIcon =
  (name: keyof typeof TAB_ICONS) =>
  ({ focused }: { focused: boolean }) => ({
    type: "image" as const,
    source: TAB_ICONS[name][focused ? "filled" : "outline"],
  });
